// # HELPER FUNCTIONS FOR KANJI
// See # KANJI LIST to manage kanji data
//
// used for converting katakana to hiragana
Kantan.katakanaToHiragana = function (str) {
  var map = {
    'ア': 'あ', 'イ': 'い', 'ウ': 'う', 'エ': 'え', 'オ': 'お',
    'カ': 'か', 'キ': 'き', 'ク': 'く', 'ケ': 'け', 'コ': 'こ',
    'サ': 'さ', 'シ': 'し', 'ス': 'す', 'セ': 'せ', 'ソ': 'そ',
    'タ': 'た', 'チ': 'ち', 'ツ': 'つ', 'テ': 'て', 'ト': 'と',
    'ナ': 'な', 'ニ': 'に', 'ヌ': 'ぬ', 'ネ': 'ね', 'ノ': 'の',
    'ハ': 'は', 'ヒ': 'ひ', 'フ': 'ふ', 'ヘ': 'へ', 'ホ': 'ほ',
    'マ': 'ま', 'ミ': 'み', 'ム': 'む', 'メ': 'め', 'モ': 'も',
    'ヤ': 'や', 'ユ': 'ゆ', 'ヨ': 'よ',
    'ラ': 'ら', 'リ': 'り', 'ル': 'る', 'レ': 'れ', 'ロ': 'ろ',
    'ワ': 'わ', 'ヲ': 'を', 'ン': 'ん',
    'ガ': 'が', 'ギ': 'ぎ', 'グ': 'ぐ', 'ゲ': 'げ', 'ゴ': 'ご',
    'ザ': 'ざ', 'ジ': 'じ', 'ズ': 'ず', 'ゼ': 'ぜ', 'ゾ': 'ぞ',
    'ダ': 'だ', 'ヂ': 'ぢ', 'ヅ': 'づ', 'デ': 'で', 'ド': 'ど',
    'バ': 'ば', 'ビ': 'び', 'ブ': 'ぶ', 'ベ': 'べ', 'ボ': 'ぼ',
    'パ': 'ぱ', 'ピ': 'ぴ', 'プ': 'ぷ', 'ペ': 'ぺ', 'ポ': 'ぽ',
    'ァ': 'ぁ', 'ィ': 'ぃ', 'ゥ': 'ぅ', 'ェ': 'ぇ', 'ォ': 'ぉ',
    'ッ': 'っ', 'ャ': 'ゃ', 'ュ': 'ゅ', 'ョ': 'ょ',
    'ヮ': 'ゎ', 'ヴ': 'ゔ', 'ヵ': 'か', 'ヶ': 'け'
  }, i = 0, j = str.length, string = '';
  
  for (; i < j; i++) {
    if (map[str[i]]) {
      string += map[str[i]];
    } else {
      string += str[i];
    }
  }
  
  return string;
};


/*
  SYNTAX
  
  Kantan.kanjiQuizlet(['一', '二', '三', '四', '五', '六', '七', '八', '九', '十', '百', '千', '万', '円', '時'], 'meanings|readings|stroke', {
    hiraganaOnly : true // converts katakana for onyomi into hiragana
  });
*/
// returns object/array based on exercise type
Kantan.kanjiQuizlet = function (kanji, type, settings) {
  settings = settings || {};
  kanji = kanji || [];
  type = (type || 'meanings').toLowerCase(); 
  var o = type == 'stroke' ? [] : {}, i = 0, j = kanji.length;
  
  // generate quizlet
  for (; i < j; i++) {
    if (Kantan.kanji[kanji[i]]) {
      switch (type) {
        case 'meanings':
          o[kanji[i]] = Kantan.kanji[kanji[i]].meaning;
          break;

        case 'readings':
          o[kanji[i] + '|' + Kantan.kanji[kanji[i]].meaning] = ((settings.hiraganaOnly ? Kantan.katakanaToHiragana(Kantan.kanji[kanji[i]].onyomi) : Kantan.kanji[kanji[i]].onyomi) || '') + '|' + (Kantan.kanji[kanji[i]].kunyomi || '');
          break;

        case 'stroke':
          o.push({
            kanji : kanji[i],
            meaning : Kantan.kanji[kanji[i]].meaning,
            reading : ((settings.hiraganaOnly ? Kantan.katakanaToHiragana(Kantan.kanji[kanji[i]].onyomi) : Kantan.kanji[kanji[i]].onyomi) || '') + '|' + (Kantan.kanji[kanji[i]].kunyomi || ''),
            strokes : Kantan.kanji[kanji[i]].strokes,
            order : Kantan.kanji[kanji[i]].order,
            example_words : Kantan.kanji[kanji[i]].example_words
          });
          break;

        default:
          break;
      }
      
    } else {
      console.error('kanjiQuizlet ERROR: "' + kanji[i] + '" cannot be found in kanji.js. Please verify that this kanji is available in kanji.js or check for any typos in this entry.');
    }
  }
  
  return o;
};


// parses example words as an HTML string for use in exercises and more
Kantan.parse.exampleWords = function (examples, type) {
  if (examples) {
    var i = 0, j = examples.length, str = '', word, meaning, k;
    
    // plain string
    if (type == 'plain') {
      for (; i < j; i++) {
        for (k in examples[i]) {
          word = k.split('|');
          str += (word[1] ? word[0] + ' (' + word[1] + ')' : word[0]) + ' ' + examples[i][k] + '\n';
        }
      }
      
      return str.replace(/\n$/, '');
    }
    
    else {
      for (str = '<ul class="example-words">'; i < j; i++) {
        for (k in examples[i]) {
          word = k.split('|');
          str += '<li>' + (word[1] ? '<ruby>' + word[0] + '<rt>' + word[1] + '</rt></ruby>' : word[0]) + ' ' + examples[i][k] + '</li>';
        }
      }

      return str + '</ul>';
    }
  }
};


// parses words on /lessons/kanji-list/ pages
// EXAMPLE BELOW
/*
  Kantan.parse.kanjiList({
    // No settings yet
  });
*/
Kantan.parse.kanjiList = function (settings) {
  settings = settings || {};
  
  for (var row = document.querySelectorAll('.list-table [data-kanji]'), i = 0, j = row.length, char, kanji; i < j; i++) {
    char = row[i].dataset.kanji;
    kanji = Kantan.kanji[char];
    
    if (kanji) {
      row[i].innerHTML = row[i].innerHTML
        .replace('{KANJI}', '<span class="big-kanji">' + char + '</span>')
        .replace('{MEANING}', '<div class="kanji-list-meaning label-value"><span class="label">Meaning:</span><span class="value">' + kanji.meaning + '</span></div>')
        .replace('{READING}', 
          '<div class="kanji-list-reading label-value">'+
            (kanji.onyomi ? '<span class="label">Onyomi:</span><span class="value">' + kanji.onyomi + '</span><br>' : '')+
            (kanji.kunyomi ? '<span class="label">Kunyomi:</span><span class="value">' + kanji.kunyomi + '</span>' : '')+
          '</div>'
        )
        .replace('{STROKE_COUNT}', '<div class="kanji-list-stroke-count label-value"><span class="label">Strokes:</span><span class="value">' + kanji.strokes + '</span></div>')
        .replace('{STROKE_ORDER}',
          '<div class="kanji-list-stroke-order">'+
            '<span class="button-container"><button class="button icon-only round reibun" onclick="Kantan.viewStrokeOrder(\'' + char + '\', \'' + kanji.order + '\');" title="View stroke order"><i class="fa">&#xf002;</i> </button></span>'+
            '<img src="' + getPaths() + 'resources/images/stroke-order/img/' + kanji.order + '.webp">'+
          '</div>'
        )
        .replace('{EXAMPLE_WORDS}', Kantan.parse.exampleWords(kanji.example_words).replace('example-words', 'example-words clear') + '<hr>');
    }
  }
};


